sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float iso;
uniform float shadowBias;
uniform float chroma;
uniform float blotch;
uniform float noiseSize;
uniform float speed;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
float3 unp(float4 c) {
    return c.rgb / max(c.a, 0.0001);
}
float luma(float3 c) {
    return dot(c, float3(0.2126, 0.7152, 0.0722));
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
float hash21(float2 p) {
    return fract(sin(dot(p, float2(127.1, 311.7))) * 43758.5453);
}
float vnoise(float2 p) {
    float2 i = floor(p);
    float2 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    float a = hash21(i);
    float b = hash21(i + float2(1.0, 0.0));
    float c = hash21(i + float2(0.0, 1.0));
    float d = hash21(i + float2(1.0, 1.0));
    return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float3 s = unp(c);
    float t = floor(time * speed);
    float2 p = coord / max(noiseSize, 0.5) + t * 19.3;
    float l = luma(s);
    float weight = mix(1.0, 1.0 - l, shadowBias);
    float ln = hash21(p) - 0.5;
    float3 cn = float3(hash21(p + 2.1), hash21(p + 6.7), hash21(p + 9.3)) - 0.5;
    float b = vnoise(coord / (noiseSize * 12.0) + t * 3.1) - 0.5;
    float3 o = s + (float3(ln) + cn * chroma + float3(b * blotch * 2.0)) * iso * weight * 0.5;
    return fin(c, float4(max(o, float3(0.0)) * c.a, c.a), opacity);
}
